-- f7f4eee9 English: %s classification {{!is|is not}} %s
[3612] = "%s分类{{!是|不是}}%s",
-- 7d66ae03 English: %s {{!is|is not}} active
[3613] = "%s{{!正在|没有}}生效",
-- 8f9c8fcf English: %s {{!is|is not}} active or pending
[3614] = "%s{{!正在生效或待生效|未生效也未待生效}}",
