[3615] = "%s{{!正在|没有}}生效，且%s",
-- fb5dc62c English: %s {{!is|is not}} available
[3616] = "%s{{!可用|不可用}}",
-- cb0383c3 English: %s {{!is|is not}} beyond melee range
[3617] = "%s{{!已|未}}超出近战范围",
