[3619] = "%s{{!正在|没有在}}施法",
-- a1cfb513 English: %s {{!is|is not}} currently channeling
[3620] = "%s{{!正在|没有在}}引导法术",
-- 31089dcd English: {unit} {{!is|is not}} currently casting {spell}
[3621] = "{unit}{{!正在|没有在}}施放{spell}",
-- 99f8dade English: {unit} {{!is|is not}} currently channeling {spell}
